3	namespace App\Http\Requests;
4	
5	use Illuminate\Foundation\Http\FormRequest;
6	
7	// V2: Base form request with shared input sanitization helpers — trim, lowercase, and email normalization.
8	abstract class BaseFormRequest extends FormRequest
9	{
10	    /**
11	     * Authorization is enforced entirely by route middleware (VerifySupabaseJwt,
12	     * LoadCurrentProfessional, staff guards) and resource Policies invoked from
13	     * controllers via `authorizeForUser($pro, ...)`. This method is intentionally
14	     * `final` — Supabase JWT means `Auth::user()` is always null, so any logic
15	     * here would gate against a null user and create a second, inconsistent
16	     * authorization surface. Do NOT override.
17	     */
18	    final public function authorize(): bool
19	    {
20	        return true;
21	    }
22	
23	    /**
24	     * Trim string inputs.
25	     */
26	    protected function trimStrings(array $keys): void
27	    {
28	        $data = [];
29	
30	        foreach ($keys as $key) {
31	            $value = $this->input($key);
32	            if (is_string($value)) {
33	                $data[$key] = trim($value);
34	            }
35	        }
36	
37	        if (! empty($data)) {
38	            $this->merge($data);
39	        }
40	    }
41	
42	    /**
43	     * Lowercase string inputs.
44	     */
45	    protected function lowercaseStrings(array $keys): void
46	    {
47	        $data = [];
48	
49	        foreach ($keys as $key) {
50	            $value = $this->input($key);
51	            if (is_string($value)) {
52	                $data[$key] = strtolower(trim($value));
53	            }
54	        }
55	
56	        if (! empty($data)) {
57	            $this->merge($data);
58	        }
59	    }
60	
61	    /**
62	     * Sanitize email inputs (trim and lowercase).
63	     */
64	    protected function sanitizeEmails(array $keys): void
65	    {
66	        $this->lowercaseStrings($keys);
67	    }
68	
69	    /**
70	     * Normalize phone-like inputs to digits and a leading `+` only.
71	     * Strips whitespace, parens, dashes, and any other punctuation. Empty
72	     * results coerce to null so downstream code never has to distinguish
73	     * '' from null. Skips keys that are absent or not strings.
74	     */
75	    protected function normalizePhones(array $keys): void
76	    {
77	        $data = [];
78	
79	        foreach ($keys as $key) {
80	            if (! $this->has($key)) {
81	                continue;
82	            }
83	            $value = $this->input($key);
84	            if (! is_string($value)) {
85	                continue;
86	            }
87	            $normalized = preg_replace('/[^\d+]/', '', trim($value));
88	            $data[$key] = $normalized === '' ? null : $normalized;
89	        }
90	
91	        if (! empty($data)) {
92	            $this->merge($data);
93	        }
94	    }
95	
96	    /**
97	     * Value-level twin of `cleanText`. Strips HTML tags, ASCII control chars,
98	     * and surrounding whitespace from a single string; returns null for empty
99	     * results AND for non-string input. Lifted out of cleanText so traits
100	     * (ValidatesProfessionalAbout) and nested-array loops (settings.*) can
101	     * share the exact same transform without re-implementing it.
102	     */
103	    protected static function cleanString(?string $value): ?string
104	    {
105	        if (! is_string($value)) {
106	            return null;
107	        }
108	        // strip_tags() leaves content inside <script>/<style> blocks — remove those blocks entirely first.
109	        $noScripts = preg_replace('/<(script|style)\b[^>]*>.*?<\/\1>/is', '', $value) ?? $value;
110	        $stripped = preg_replace('/[\x00-\x1F\x7F]/', '', strip_tags($noScripts));
111	        $cleaned = trim((string) $stripped);
112	
113	        return $cleaned === '' ? null : $cleaned;
114	    }
115	
116	    /**
117	     * Clean user-authored text inputs: strip HTML tags, ASCII control chars,
118	     * and surrounding whitespace; coerce empty results to null. Defense-in-depth
119	     * against stored XSS for fields that are echoed by the frontend. Skips keys
120	     * that are absent or not strings.
121	     */
122	    protected function cleanText(array $keys): void
123	    {
124	        $data = [];
125	
126	        foreach ($keys as $key) {
127	            if (! $this->has($key)) {
128	                continue;
129	            }
130	            $value = $this->input($key);
131	            if (! is_string($value)) {
132	                continue;
133	            }
134	            $data[$key] = static::cleanString($value);
135	        }
136	
137	        if (! empty($data)) {
138	            $this->merge($data);
139	        }
140	    }
141	
142	    /**
143	     * Lowercase email-like inputs and coerce empty strings to null. Use this
144	     * for fields backed by a unique index where the difference between '' and
145	     * null matters (e.g. professionals.primary_email). For looser semantics
146	     * use `sanitizeEmails`.
147	     */
148	    protected function lowercaseEmails(array $keys): void
149	    {
150	        $data = [];
151	
152	        foreach ($keys as $key) {
153	            if (! $this->has($key)) {
154	                continue;
155	            }
156	            $value = $this->input($key);
157	            if (! is_string($value)) {
158	                continue;
159	            }
160	            $normalized = mb_strtolower(trim($value));
161	            $data[$key] = ($normalized === '') ? null : $normalized;
162	        }
163	
164	        if (! empty($data)) {
165	            $this->merge($data);
166	        }
167	    }
168	}
