3	namespace App\Http\Requests\Api;
4	
5	use App\Http\Controllers\Concerns\DetectsClientInfo;
6	use App\Http\Requests\BaseFormRequest;
7	use App\Http\Requests\Concerns\NormalizesProfessionalType;
8	use App\Models\Core\Professional\Professional;
9	use Illuminate\Validation\Rule;
10	
11	// V2: Validates professional onboarding/bootstrap — display name, email, phone, handle generation, and professional type normalization.
12	class BootstrapRequest extends BaseFormRequest
13	{
14	    use DetectsClientInfo;
15	    use NormalizesProfessionalType;
16	
17	    public function rules(): array
18	    {
19	        $uid = $this->attributes->get('supabase_uid');
20	
21	        $existingProfessionalId = null;
22	        if (is_string($uid) && $uid !== '') {
23	            $existingProfessionalId = Professional::query()
24	                ->where('auth_user_id', $uid)
25	                ->value('id');
26	        }
27	
28	        $professionalTypeRules = is_string($existingProfessionalId) && $existingProfessionalId !== ''
29	            ? ['sometimes', 'required']
30	            : ['required'];
31	
32	        return [
33	            'handle' => ['sometimes', 'nullable', 'string', 'max:40'],
34	            'display_name' => ['required', 'string', 'max:80'],
35	            'primary_email' => [
36	                'required', 'email:rfc', 'max:255',
37	                Rule::unique('professionals', 'primary_email')->ignore($existingProfessionalId, 'id'),
38	            ],
39	            'phone' => ['required', 'string', 'max:40'],
40	            'first_name' => ['required', 'string', 'max:80'],
41	            'last_name' => ['nullable', 'string', 'max:80'],
42	            // ISO 3166-1 alpha-2 only. Lower-case and whitespace are normalised
43	            // in prepareForValidation, so by the time we get here the value is
44	            // already two upper-case letters. Nullable because the CDN-header
45	            // fallback (also in prepareForValidation) handles the common case
46	            // where the frontend doesn't explicitly collect country.
47	            'country_code' => ['nullable', 'string', 'size:2', 'regex:/^[A-Z]{2}$/'],
48	            'timezone' => ['nullable', 'string', 'max:64'],
49	            'invite_token' => ['sometimes', 'nullable', 'string', 'max:80'],
50	            'brand_partner_professional_id' => ['sometimes', 'nullable', 'uuid', Rule::exists('professionals', 'id')],
51	            'join_brand_handle' => ['sometimes', 'nullable', 'string', 'max:50'],
52	            'shopify_setup_token' => ['sometimes', 'nullable', 'string', 'size:64', 'regex:/^[a-f0-9]{64}$/'],
53	            'professional_type' => [
54	                ...$professionalTypeRules,
55	                'string',
56	                Rule::in(array_keys(config('sidest.professional_types', []))),
57	            ],
58	            'handle_lc' => [
59	                'sometimes',
60	                'nullable',
61	                'string',
62	                'max:50',
63	                Rule::unique('professionals', 'handle_lc')->ignore($existingProfessionalId, 'id'),
64	            ],
65	        ];
66	    }
67	
68	    protected function prepareForValidation(): void
69	    {
70	        $this->trimStrings([
71	            'handle', 'display_name', 'phone', 'first_name',
72	            'last_name', 'country_code', 'timezone', 'professional_type', 'invite_token',
73	        ]);
74	        $this->sanitizeEmails(['primary_email']);
75	
76	        // For brands: force handle to match display_name
77	        $professionalType = mb_strtolower(trim((string) ($this->professional_type ?? '')));
78	        $isBrand = $professionalType === 'brand';
79	
80	        $handle = $this->handle;
81	        if ($isBrand) {
82	            // Brand handle always derived from display_name to prevent duplicate brand names
83	            $handle = $this->generateHandleFromDisplayName($this->display_name ?? '');
84	        } elseif (! is_string($handle) || $handle === '') {
85	            $handle = $this->generateHandleFromDisplayName($this->display_name ?? '');
86	        }
87	
88	        $merge = [
89	            'handle' => $handle,
90	            'handle_lc' => is_string($handle) ? strtolower(trim($handle)) : null,
91	        ];
92	
93	        if ($this->exists('professional_type')) {
94	            $merge['professional_type'] = $this->normalizeProfessionalTypeInput($this->professional_type);
95	        }
96	
97	        if ($this->exists('invite_token')) {
98	            $merge['invite_token'] = is_string($this->invite_token) ? trim($this->invite_token) : null;
99	        }
100	
101	        if ($this->exists('brand_partner_professional_id')) {
102	            $merge['brand_partner_professional_id'] = is_string($this->brand_partner_professional_id)
103	                ? trim($this->brand_partner_professional_id)
104	                : null;
105	        }
106	
107	        if ($this->exists('join_brand_handle')) {
108	            $merge['join_brand_handle'] = is_string($this->join_brand_handle)
109	                ? strtolower(trim($this->join_brand_handle))
110	                : null;
111	        }
112	
113	        if ($this->exists('shopify_setup_token')) {
114	            $merge['shopify_setup_token'] = is_string($this->shopify_setup_token)
115	                ? trim($this->shopify_setup_token)
116	                : null;
117	        }
118	
119	        // Resolve country_code: explicit request value first (uppercased),
120	        // then CDN header detection (Cloudflare / CloudFront / Vercel). The
121	        // fallback keeps non-AU affiliates from silently getting an
122	        // Australian Express account at Stripe onboarding time. If neither
123	        // source yields a valid ISO alpha-2 code, country_code stays null
124	        // and the Stripe createConnectAccount guard will 422 when they try
125	        // to connect.
126	        $providedCountry = is_string($this->country_code) ? strtoupper(trim($this->country_code)) : '';
127	        $resolvedCountry = $providedCountry !== '' ? $providedCountry : $this->detectCountryCode($this);
128	        if ($resolvedCountry !== null && $resolvedCountry !== '') {
129	            $merge['country_code'] = $resolvedCountry;
130	        }
131	
132	        $this->merge($merge);
133	    }
134	
135	    private function generateHandleFromDisplayName(string $displayName): string
136	    {
137	        // Convert display name to slug (e.g., "Josh's Barbershop" -> "joshs-barbershop")
138	        $base = \Illuminate\Support\Str::slug($displayName);
139	
140	        if ($base === '' || $base === '-') {
141	            $base = 'professional';
142	        }
143	
144	        // Check if handle is available, if not append numbers
145	        $handle = $base;
146	        $attempt = 1;
147	        while (Professional::query()->where('handle_lc', strtolower($handle))->exists()) {
148	            $handle = $base.$attempt;
149	            $attempt++;
150	        }
151	
152	        return $handle;
153	    }
154	}
