7	// V2: Validates Google Business Profile upsert — place ID, name, address, coordinates, phone, website, and hours array.
8	class UpsertGoogleBusinessProfileRequest extends BaseFormRequest
9	{
10	    protected function prepareForValidation(): void
11	    {
12	        $hours = $this->input('hours');
13	        if (is_array($hours)) {
14	            $hours = array_values(array_filter(array_map(function ($value) {
15	                return is_string($value) ? trim($value) : '';
16	            }, $hours), fn ($value) => $value !== ''));
17	        } else {
18	            $hours = [];
19	        }
