51	    private function normalizeEmail(mixed $value): mixed
52	    {
53	        if (! is_string($value)) {
54	            return $value;
55	        }
56	
57	        $normalized = mb_strtolower(trim($value));
58	
59	        return $normalized !== '' ? $normalized : null;
60	    }
61	
62	    private function normalizePhone(mixed $value): mixed
63	    {
64	        if (! is_string($value)) {
65	            return $value;
66	        }
67	
68	        $normalized = preg_replace('/[^\d+]/', '', trim($value));
69	        if (! is_string($normalized) || $normalized === '') {
70	            return null;
71	        }
72	
73	        if (str_contains($normalized, '+')) {
74	            $normalized = '+'.str_replace('+', '', $normalized);
75	        }
76	
77	        return $normalized;
78	    }
79	
80	    private function normalizeApplicantType(mixed $value): mixed
81	    {
82	        if (! is_string($value)) {
83	            return $value;
84	        }
85	
86	        $normalized = mb_strtolower(trim($value));
87	        if ($normalized === '') {
88	            return null;
89	        }
90	
91	        $compact = preg_replace('/[^a-z]+/u', '', $normalized) ?? $normalized;
92	
93	        return match ($compact) {
94	            'professional', 'proffesional', 'profesisonal' => 'professional',
95	            'influencer' => 'influencer',
96	            'brand' => 'brand',
97	            'other' => 'other',
98	            default => str_replace([' ', '-'], '_', $normalized),
99	        };
100	    }
101	
102	    private function normalizeIndustry(mixed $value): mixed
103	    {
104	        if (! is_string($value)) {
105	            return $value;
106	        }
107	
108	        $normalized = mb_strtolower(trim($value));
109	        if ($normalized === '') {
110	            return null;
111	        }
112	
113	        $compact = preg_replace('/[^a-z]+/u', '', $normalized) ?? $normalized;
114	
115	        return match ($compact) {
116	            'mensgrooming' => 'mens_grooming',
117	            'womenshaircare' => 'womens_haircare',
118	            'beautyproducts' => 'beauty_products',
119	            'vitaminsandsupplements' => 'vitamins_and_supplements',
120	            'servicesandsoftware' => 'services_and_software',
121	            'other' => 'other',
122	            default => str_replace([' ', '-'], '_', $normalized),
123	        };
124	    }
125	
126	    private function normalizeOptionalString(mixed $value): mixed
127	    {
128	        if (! is_string($value)) {
129	            return $value;
130	        }
131	
132	        $normalized = trim($value);
133	
134	        return $normalized !== '' ? $normalized : null;
135	    }
136	
137	    private function normalizeBoolean(mixed $value): mixed
138	    {
139	        if (is_bool($value)) {
140	            return $value;
141	        }
142	
143	        if ($value === null || $value === '') {
144	            return null;
145	        }
146	
147	        $parsed = filter_var($value, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE);
148	
149	        return $parsed ?? $value;
150	    }
151	
152	    private function normalizeInteger(mixed $value): mixed
153	    {
154	        if (is_int($value) || $value === null) {
155	            return $value;
156	        }
157	
158	        if (is_float($value) && floor($value) === $value) {
159	            return (int) $value;
160	        }
161	
162	        if (! is_string($value)) {
163	            return $value;
164	        }
165	
166	        $normalized = trim($value);
167	        if ($normalized === '') {
168	            return null;
169	        }
170	
171	        return preg_match('/^-?\d+$/', $normalized) === 1
172	            ? (int) $normalized
173	            : $value;
174	    }
175	}
